<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Notification extends Model{protected $fillable=['organization_id','user_id','type','schema_version','category','actor_id','resource_type','resource_id','action_url','data','requires_action','action_state','title','message','severity','read_at','dismissed_at','deduplication_key'];protected $casts=['read_at'=>'datetime','dismissed_at'=>'datetime','data'=>'array','requires_action'=>'boolean'];public function actor(){return $this->belongsTo(User::class,'actor_id');}public function organization(){return $this->belongsTo(Organization::class);}}
